head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.sKEY = "";
scwin.sGubun = "";

// 팩스첨부문서

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {

};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91100.btn_close_onclick" });
    }
};

/**
 * @method
 * @name grd_FileList_OnDblClick
 * @description grd_FileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_FileList_OnDblClick = function(row, colid) {
    try {
        if (row === 0) return;
        // 파일 다운로드
        scwin.downloadFile();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS91100.grd_FileList_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_FileList_OnLoadError
 * @description dts_FileList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_FileList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_FileList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91100.dts_FileList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_FileList_OnLoadCompleted
 * @description dts_FileList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_FileList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_FileList.errorMsg) {
            await $c.win.alert(dts_FileList.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91100.dts_FileList_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 1 : 발행기관신청,  팩스-발행기관신청  2:표준코드신청, 팩스-표준코드신청   3:팩스-다운로드IP  로 넣어주세요~~~

/**
 * @method
 * @name ins_search
 * @description 발행기관 신청 상세정보
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // Lodaing~~~ 표시
    // alert( url);
    const sbmOptions = {
        id : "sbm_dts_FileList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_FileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name downloadFile
 * @description 파일다운로드
 * @returns {void}
 * @hidden N
 */
scwin.downloadFile = function() {
    $c.stf.doLogSave("ULDINS91100.xml", SCREN_PROCS_TP_CD_08);
    const nRow = dts_FileList.getRowPosition();
    const sKEY1 = dts_FileList.getCellData(nRow, "KEY1");
    const sKEY2 = dts_FileList.getCellData(nRow, "KEY2");
    const sGubun = dts_FileList.getCellData(nRow, "FILE_DN_FG");

    // GUBUN
    // 1 : 발행기관신청 첨부파일
    // 2 : 표준코드신청 첨부파일
    // 3 : FAX 첨부파일
    location.href = "/filedownload.do?KEY1=" + sKEY1 + "&KEY2=" + sKEY2 + "&GUBUN=" + scwin.sGubun;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    const arrPar = new Array();
    const parentWin = $c.frame.path("../");
    const fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar !== undefined) {
        fn_GetPar(arrPar);
        scwin.sKEY = arrPar[0];
        scwin.sGubun = arrPar[1];
        if (scwin.sKEY === "") {
            await $c.win.alert("조회 키(접수번호 등)가 없습니다.");
            await $c.win.closePopup();
            return;
        }
        if (scwin.sGubun === "") {
            const sMsg = "구분값이 없습니다. \n\n" + "1 : 발행기관신청, 팩스-발행기관신청 \n" + "2 : 표준코드신청, 팩스-표준코드신청 \n" + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n";
            await $c.win.alert(sMsg);
            await $c.win.closePopup();
            return;
        }
        await scwin.ins_search();
    }
};
